'use strict';
const $ = s => document.querySelector(s);
const esc = x => String(x ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = x => structuredClone(x);
const localTime = value => new Date(value).toLocaleString();
const returnStatus = value => ({accepted:'Accepted for comparison',duplicate:'Already imported',stale:'Old version — a new review is needed',conflict:'Different result — compare before deciding'})[value] || value;
const uid = prefix => `${prefix}-${crypto.randomUUID().slice(0,8)}`;
const unknown = () => ({raw:null,normalized:null,missing_reason:'not_recorded',evidence:[],inherited_from:null});
const S = {me:null, rows:[], members:[], detail:null, content:null, tab:'items', page:0, zoom:100, rotate:0, dirty:false, epoch:0, saving:null, conflict:false, timer:null, decision:false, selected:new Set(), filter:null};
const owner = () => S.me?.role === 'owner';
const editable = () => S.decision || (S.detail?.task && ['assigned','in_progress'].includes(S.detail.task.status));
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('show'); setTimeout(()=>$('#toast').classList.remove('show'),6000); }
async function api(path, body, method) {
  const options={method:method || (body === undefined?'GET':'POST'),headers:{}};
  if(body !== undefined) { options.headers['X-CSRF-Token']=S.me?.csrf || ''; if(body instanceof FormData) options.body=body; else {options.headers['Content-Type']='application/json'; options.body=JSON.stringify(body);} }
  const response=await fetch('/api'+path,options);
  const data=await response.json().catch(()=>({error:'The server returned an unreadable response.'}));
  if(!response.ok) { const error=new Error(data.error || 'Request failed.'); error.status=response.status; error.fields=data.fields; throw error; }
  return data;
}
function modal(title, html, bind) { $('#modal-body').innerHTML=`<h2>${esc(title)}</h2>${html}`; if(!$('#modal').open) $('#modal').showModal(); bind?.(); }
$('#close-modal').onclick=()=>$('#modal').close();
function ask(question, textEntry=false) {
  return new Promise(resolve=>{
    const d=document.createElement('dialog');d.innerHTML=`<h2>${textEntry?'Add a reason':'Confirm action'}</h2><p>${esc(question)}</p>${textEntry?'<textarea aria-label="Response" id="ask-response"></textarea>':''}<div class="actions"><button data-accept class="primary">Continue</button><button data-cancel class="quiet">Cancel</button></div>`;document.body.append(d);
    const finish=value=>{d.close();d.remove();resolve(value);};d.querySelector('[data-accept]').onclick=()=>finish(textEntry?d.querySelector('textarea').value:true);d.querySelector('[data-cancel]').onclick=()=>finish(textEntry?null:false);d.oncancel=e=>{e.preventDefault();finish(textEntry?null:false);};d.showModal();if(textEntry)d.querySelector('textarea').focus();
  });
}
function field(label,input) { return `<label>${esc(label)}${input}</label>`; }
function input(value, attrs='') {return `<input value="${esc(value)}" ${attrs}>`;}
function select(options,value,attrs='') {return `<select ${attrs}>${options.map(x=>{const [v,l]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`;}
function download(name, data) {const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function auth() {
  $('#app').hidden=true; $('#auth').hidden=false;
  const token=new URLSearchParams(location.hash.slice(1)).get('invite');
  $('#auth').innerHTML=`<div class="auth-wrap"><section class="auth-form"><h1>Food record review</h1><h2>${token?'Accept your invitation':'Sign in'}</h2><p class="muted">${token?'Choose a password to activate your account.':'Sign in to continue your assigned reviews.'}</p><form id="login">${token?'':field('Email',input('','name="email" type="email" required autocomplete="username"'))}${field('Password',input('','name="password" type="password" required minlength="12" maxlength="256" autocomplete="'+(token?'new-password':'current-password')+'"'))}<small>Use at least 12 characters.</small><p id="auth-error" role="alert"></p><button class="primary">${token?'Activate account':'Sign in'}</button></form></section></div>`;
  $('#login').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try {if(token){await api('/accept-invite',{token,password:f.get('password')});history.replaceState(null,'',location.pathname);toast('Account activated. Sign in with your invitation email.');auth();}else{await api('/login',Object.fromEntries(f));const me=await api('/me');if(S.me && S.dirty && S.me.id!==me.id) throw new Error('Sign in with the same account to recover your unsaved draft.');S.me=me;$('#auth').hidden=true;$('#app').hidden=false;if(S.dirty&&S.detail){shell();renderRecord();}else await queue();}}catch(err){$('#auth-error').textContent=err.message;}};
}
function shell() {
  if(S.me?.offline){offlineShell();return;}
  $('#auth').hidden=true;$('#app').hidden=false;
  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">Food record review</div><nav><button data-nav="queue" class="active">Day review queue</button><button data-nav="archive">Previous record reviews</button>${owner()?'<button data-nav="grouping">Participant & date</button><button data-nav="import">Import records</button><button data-nav="offline">Offline packages</button><button data-nav="team">People & policy</button><button data-nav="releases">Research releases</button>':''}</nav><div class="sidebar-bottom"><strong>${esc(S.me.name)}</strong><small>${esc(S.me.role)} · ${esc(S.me.project_id)}</small><button id="logout">Sign out</button></div></aside><main><header class="topline"><span id="breadcrumb">Review queue</span><span class="muted">${esc(S.me.project_id)}</span></header><div id="screen"></div></main></div>`;
  document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
  $('#logout').onclick=async()=>{if(!await leave())return;await api('/logout',{});S.me=null;S.detail=null;S.filter=null;auth();};
}
async function leave() {if(S.decision&&S.dirty&&!await ask('Discard the unsaved adjudication draft?'))return false;if(S.dirty&&!S.decision){await save();if(S.dirty&&!await ask('Your draft is not saved. Leave this page anyway? Download a copy first if needed.'))return false;}clearTimeout(S.timer);S.dirty=false;S.decision=false;return true;}
async function navigate(name){if(!await leave())return;try{if(name==='queue')await queue();if(name==='team')await team();if(name==='import')importPage();if(name==='releases')await releases();if(name==='grouping')await grouping();if(name==='archive')await reviewArchive();if(name==='offline')await offlinePackages();}catch(e){toast(e.message);}}
async function queue() {
  if(S.me?.offline){await offlineQueue();return;}
  if(!S.filter)S.filter=owner()?'drafts':'all';
  S.detail=null;S.content=null;S.conflict=false;S.selected.clear();
  S.rows=await api('/records'+location.search);let unresolved=0;if(owner()){S.members=await api('/members');unresolved=(await api('/grouping')).filter(p=>p.status==='needs_confirmation').length;}shell();
  const drafts=S.rows.filter(r=>r.has_candidate).length;
  $('#screen').innerHTML=`<div class="page"><div class="page-head"><h1>Day review queue</h1></div><p class="muted">Each review covers one participant and one date, including all related source records and attachments.</p>${unresolved?`<p class="pending-bar">${unresolved} source days need identity or date confirmation. Open <button id="resolve-grouping">Participant & date</button> before assigning those days.</p>`:''}<div class="stats"><div><strong>${S.rows.length}</strong><span>Days in scope</span></div><div><strong>${drafts}</strong><span>Drafts available</span></div><div><strong>${S.rows.filter(r=>r.state==='approved').length}</strong><span>Approved days</span></div><div><strong>${S.rows.reduce((n,r)=>n+r.attachments,0)}</strong><span>Attached clarifications</span></div></div><section class="panel"><div class="toolbar"><div class="search">${input('','id="search" placeholder="Find a participant, date or record…" aria-label="Find a participant, date or record"')}</div>${select(owner()?[['drafts','Drafts available'],['all','All days'],['in_review','In review'],['ready_for_approval','Ready for approval'],['needs_adjudication','Needs adjudication'],['approved','Approved'],['excluded','Excluded'],['task:assigned','Assigned tasks'],['task:in_progress','In-progress tasks'],['task:submitted','Submitted tasks'],['task:returned','Returned tasks'],['task:stale','Stale tasks']]:[['all','All assigned days'],['task:assigned','To review'],['task:in_progress','In progress'],['task:submitted','Submitted'],['task:stale','Needs reassignment']],S.filter,'id="filter"')}<span id="count" class="muted"></span></div>${owner()?'<div class="toolbar"><span id="selection">Select days using the checkboxes below</span><button id="batch-offline" class="primary">Export review packages</button><button id="batch-assign">Assign selected</button><button id="batch-approve">Approve selected</button><button id="batch-release">Create release</button></div>':''}<div class="table-scroll"><table><thead><tr><th>${owner()?'<input type="checkbox" id="select-all" aria-label="Select visible days">':''}</th><th>Participant / date</th><th>Sources</th><th>Status</th><th>Reviews</th><th>Draft issues</th><th></th></tr></thead><tbody id="rows"></tbody></table></div><div class="empty" id="empty" hidden>No days match these filters.</div></section><p class="muted">AI drafts are not research-approved data. Approval requires completed human review.</p></div>`;
  if($('#resolve-grouping'))$('#resolve-grouping').onclick=()=>navigate('grouping');$('#search').oninput=renderRows;$('#filter').onchange=e=>{S.filter=e.target.value;renderRows();};
  if(owner()){$('#batch-offline').onclick=()=>offlineExportDialog([...S.selected]);$('#batch-assign').onclick=()=>assignDialog([...S.selected]);$('#batch-approve').onclick=()=>batchApprove([...S.selected]);$('#batch-release').onclick=()=>createRelease([...S.selected]);$('#select-all').onchange=e=>{visibleRows().forEach(r=>e.target.checked?S.selected.add(r.record_id):S.selected.delete(r.record_id));renderRows();};}
  renderRows();
}
function visibleRows(){const q=$('#search').value.toLowerCase();return S.rows.filter(r=>[r.record_id,r.subject_id,r.date,...(r.source_record_ids||[])].join(' ').toLowerCase().includes(q)&&(S.filter==='all'||S.filter==='drafts'&&r.has_candidate||r.state===S.filter||S.filter.startsWith('task:')&&r.tasks.some(t=>t.status===S.filter.slice(5))));}
function renderRows(){const rows=visibleRows();$('#count').textContent=`${rows.length} days`;$('#empty').hidden=!!rows.length;
  $('#rows').innerHTML=rows.map(r=>`<tr><td>${owner()?`<input type="checkbox" data-pick="${esc(r.record_id)}" aria-label="Select ${esc(r.record_id)}" ${S.selected.has(r.record_id)?'checked':''}>`:''}</td><td><b>${esc(r.subject_id)} · ${esc(r.date)}</b><small>${esc((r.source_record_ids||[]).join(", "))}</small><small>Group version ${r.input_version}</small></td><td>${r.pages} pages<small>${r.attachments} attachments</small></td><td><span class="badge ${r.state==='approved'?'green':''}">${esc(r.state.replaceAll('_',' '))}</span></td><td>${r.submitted} / ${r.required_reviews}<small>submitted / required</small><small>${esc([...new Set(r.tasks.map(t=>t.status))].join(', '))}</small></td><td>${r.issues?`<span class="badge amber">${r.issues} issues</span>`:'—'}</td><td><button data-open="${esc(r.record_id)}">Open</button></td></tr>`).join('');
  document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openRecord(b.dataset.open));document.querySelectorAll('[data-pick]').forEach(b=>b.onchange=()=>{b.checked?S.selected.add(b.dataset.pick):S.selected.delete(b.dataset.pick);$('#selection').textContent=`${S.selected.size} selected`;});if(owner())$('#selection').textContent=`${S.selected.size} selected`;
}
function memberOptions(){return S.members.filter(m=>m.active).map(m=>[m.id,`${m.name} (${m.email})`]);}
function dayLabel(id){const r=S.rows.find(x=>x.record_id===id)||(S.detail?.record_id===id?S.detail:null);return r?`${r.subject_id} · ${r.date}`:id;}
function memberName(id){return S.members.find(m=>m.id===id)?.name || (id===S.me.id?S.me.name:id);}
function assignDialog(ids){if(!ids.length)return toast('Select at least one day.');modal('Assign daily reviews',`<p>Each assignment includes all source records for the participant and date, with their attachments. Independent reviewers receive the same frozen draft.</p><form id="assign-form">${field('Reviewer',select(memberOptions(),S.me.id,'name="assignee_id"'))}${field('Due date (optional)',input('','type="date" name="due_at"'))}<p>${esc(ids.map(id=>{const r=S.rows.find(x=>x.record_id===id)||S.detail;return r?`${r.subject_id} · ${r.date}`:id;}).join(', '))}</p><button class="primary">Create assignments</button></form>`,()=>{$('#assign-form').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));const results=await api('/assign',{record_ids:ids,...f,due_at:f.due_at||null});$('#modal').close();toast(results.map(r=>r.error?`${r.record_id}: ${r.error}`:`${r.record_id}: assigned`).join('\n'));if(S.detail)await openRecord(S.detail.record_id);else await queue();}catch(e){toast(e.message);}};});}
async function batchApprove(ids){if(!ids.length)return toast('Select at least one day.');try{const results=await api('/approve',{record_ids:ids});modal('Approval results',results.map(r=>`<p><b>${esc(dayLabel(r.record_id))}</b> — ${esc(r.error||'Approved')}</p>`).join(''));if(S.detail)await openRecord(S.detail.record_id);else await queue();}catch(e){toast(e.message);}}
async function createRelease(ids){if(!ids.length)return toast('Select approved days first.');try{const r=await api('/releases',{record_ids:ids});modal('Research release created',`<p>This snapshot will not change when later records or attachments arrive.</p><a class="button primary" href="/api/releases/${esc(r.id)}/download">Download CSV + JSON archive</a>`);}catch(e){toast(e.message);}}
async function openRecord(id){try{if(S.dirty&&!await leave())return;S.detail=await api('/records/'+encodeURIComponent(id));S.content=clone(S.detail.content);S.page=0;S.zoom=100;S.rotate=0;S.dirty=false;S.conflict=false;S.decision=false;S.tab='items';if(!$('#screen'))shell();renderRecord();}catch(e){toast(e.message);}}
function pages(){return Object.entries(S.detail.snapshot.documents).flatMap(([id,doc])=>Array.from({length:doc.page_count},(_,i)=>({id,page:i+1,role:doc.role})));}
function renderRecord(){const d=S.detail;const reviewing=!!d.task&&['assigned','in_progress'].includes(d.task.status);const canApprove=d.submissions.length>=d.required_reviews&&!d.tasks.some(t=>['assigned','in_progress'].includes(t.status));$('#breadcrumb').textContent=`${d.subject_id} · ${d.date}`;
  $('#screen').innerHTML=`<header class="review-header"><div><button id="back" class="quiet">← Queue</button><h1>${esc(d.subject_id)} · ${esc(d.date)} <span class="badge">${d.approved_id?'Approved':d.task?.status==='submitted'?'Review submitted':'Version '+d.input_version}</span></h1><p class="muted">${esc((d.source_record_ids||[]).join(", "))}</p><p class="muted">${S.content?S.content.items.length:0} food items · ${pages().length} source pages · ${d.required_reviews} review${d.required_reviews>1?'s':''} required</p></div><div class="actions"><span id="save-status" class="save-status">${S.decision?'Adjudication draft':editable()?'All changes saved':(d.display_mode||'Read-only preview').replaceAll('_',' ')}</span>${editable()?`<button id="confirm-sources">Pages checked: ${confirmedPages()}/${pages().length}</button><button id="save-now">Save now</button>`:''}${owner()&&!reviewing&&!S.decision&&!d.approved_id?'<button id="assign-record">Assign to colleague</button>':''}${owner()&&!d.task&&!d.approved_id&&!d.submissions.length?'<button id="start-my-review" class="primary">Start my review</button>':''}${S.me?.offline&&d.task?.status==='submitted'?'<button id="reopen-review" class="primary">Edit review</button>':''}${reviewing&&!S.decision?'<button id="submit" class="primary">Submit review</button>':''}${owner()&&!reviewing&&!S.decision&&canApprove&&!d.approved_id?'<button id="approve-record" class="primary">Approve for research</button>':''}</div></header><div id="conflict-banner" class="pending-bar" hidden></div><div class="review-workspace"><section class="source-pane"><section id="metadata-banner" class="metadata-banner" aria-label="Source metadata"></section><div class="source-controls"><button id="prev-source" aria-label="Previous source page">←</button><button id="next-source" aria-label="Next source page">→</button>${select(pages().map((p,i)=>[String(i),`${p.id} · Page ${p.page} · ${p.role}`]),String(S.page),'id="source-page" aria-label="Source page"')}<button id="zoom-out" aria-label="Zoom out">−</button><span id="zoom-label">${S.zoom}%</span><button id="zoom-in" aria-label="Zoom in">+</button><button id="rotate" aria-label="Rotate source">↻</button></div><div class="source-viewer"><div id="source-canvas" class="source-canvas"><div id="image-layer" class="image-layer"><img id="scan" alt="Original handwritten source page"><div id="evidence-box" class="evidence-box" hidden></div></div></div></div><div id="source-caption" class="source-caption">Original source · Scroll to inspect handwriting. Select a field’s source to locate its evidence.</div><div id="page-check" class="page-check"></div></section><section class="editor-pane"><nav class="tabs">${[['items','Food items'],['pages','Page coverage'],['issues','Issues'],['review','Review & help']].filter(([id])=>!S.me?.offline||id!=='review').map(([id,title])=>`<button data-tab="${id}" class="${S.tab===id?'active':''}">${title}</button>`).join('')}</nav><div id="editor" class="editor-scroll"></div></section></div>`;
  $('#back').onclick=()=>navigate('queue');$('#source-page').onchange=e=>{S.page=Number(e.target.value);showPage();};$('#zoom-in').onclick=()=>{S.zoom=Math.min(300,S.zoom+25);transformScan();};$('#zoom-out').onclick=()=>{S.zoom=Math.max(50,S.zoom-25);transformScan();};$('#rotate').onclick=()=>{S.rotate=(S.rotate+90)%360;transformScan();};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{S.tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));renderEditor();});
  if($('#reopen-review'))$('#reopen-review').onclick=async()=>{const b=$('#reopen-review');b.disabled=true;try{await api('/tasks/'+d.task.id+'/reopen',{revision:d.task.revision});await openRecord(d.record_id);toast('Review reopened. Submit again and export a new result ZIP after making changes.');}catch(err){toast(err.message);b.disabled=false;}};
  if($('#confirm-sources'))$('#confirm-sources').onclick=showCoverage;
  if($('#save-now'))$('#save-now').onclick=()=>S.decision?saveDecision():save();if($('#assign-record'))$('#assign-record').onclick=()=>assignDialog([d.record_id]);if($('#approve-record'))$('#approve-record').onclick=()=>batchApprove([d.record_id]);if($('#submit'))$('#submit').onclick=submit;
  if($('#start-my-review'))$('#start-my-review').onclick=startMyReview;$('#prev-source').onclick=()=>{if(S.page>0){S.page--;showPage();}};$('#next-source').onclick=()=>{if(S.page<pages().length-1){S.page++;showPage();}};showPage();renderEditor();
}
function renderMetadataBanner(p){const banner=$('#metadata-banner');if(!banner)return;const m=S.detail.snapshot.metadata[p?.id]||{};const fields=[['Record',p?.id],['Participant',m.subject_id],['Intake date',m.date],['Data type',m.data_type],['Timepoint',m.timepoint]];banner.innerHTML=`<div class="metadata-heading">Metadata <span>${p?.role==='attachment'?'Current attachment':'Current source'} · Read only</span></div><dl>${fields.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value||'Not provided')}</dd></div>`).join('')}</dl>${m.flag?`<p class="metadata-note"><strong>Flag:</strong> ${esc(m.flag)}</p>`:''}`;}
function showPage(evidence){const p=pages()[S.page];renderMetadataBanner(p);if(!p){$('#scan').removeAttribute('src');renderPageCheck();return;}$('#source-page').value=String(S.page);$('#scan').style.visibility='hidden';$('#scan').onload=()=>{$('#scan').style.visibility='visible';renderPageCheck();};$('#scan').onerror=()=>{$('#source-caption').textContent='Source unavailable. Your assignment may have changed; refresh the record.';renderPageCheck();};$('#scan').src=`/api/records/${encodeURIComponent(S.detail.record_id)}/source/${encodeURIComponent(p.id)}/${p.page}`;$('#source-caption').textContent=evidence?`${evidence.region} · ${evidence.transcription_raw||'Source evidence'}`:`${p.id} · Page ${p.page} · ${p.role==='main'?'Original food record':'Attachment for clarification'}`;const box=$('#evidence-box');box.hidden=!evidence?.bbox;if(evidence?.bbox){const [x,y,x2,y2]=evidence.bbox;Object.assign(box.style,{left:x*100+'%',top:y*100+'%',width:(x2-x)*100+'%',height:(y2-y)*100+'%'});}transformScan();renderPageCheck();}
async function startMyReview(){const button=$('#start-my-review');button.disabled=true;try{const rows=await api('/assign',{record_ids:[S.detail.record_id],assignee_id:S.me.id});if(rows[0].error)throw new Error(rows[0].error);await openRecord(S.detail.record_id);}catch(e){toast(e.message);button.disabled=false;}}
const attachmentUseOptions=[['','Choose how this attachment was used'],['clarify','Used to clarify this day’s food record'],['no_change','Checked; no change to this day’s food record'],['not_intake','Context only; not counted as intake']];
function renderPageCheck(){const p=pages()[S.page];if($('#prev-source'))$('#prev-source').disabled=S.page===0;if($('#next-source'))$('#next-source').disabled=S.page>=pages().length-1;if(!$('#page-check'))return;if(!p){$('#page-check').innerHTML='';return;}const c=S.content?.pages.find(x=>x.source_record_id===p.id&&x.page_number===p.page);const checked=!!c?.reviewed&&(c.classification==='blank'||c.regions.some(x=>x.trim()));$('#page-check').innerHTML=`<div class="page-check-status"><strong>Page ${S.page+1} of ${pages().length}</strong><span>${checked?'Checked':'Not checked yet'}</span></div>${editable()?`${p.role==='attachment'?field('Attachment use',select(attachmentUseOptions, attachmentUseOptions.find(x=>x[1]===c?.notes)?.[0]||'', 'id="attachment-use"')):''}<button id="check-current" ${checked||$('#scan')?.style.visibility==='hidden'?'disabled':''}>${checked?'Page checked':'I checked the whole page'}</button><small>Confirms all food rows and notes on the displayed page.</small><button id="page-details" class="quiet small">${checked?'Edit page check / notes':'Page details / partial review'}</button>`:''}`;if($('#attachment-use'))$('#attachment-use').onchange=e=>{if(!e.target.value)return;let page=S.content.pages.find(x=>x.source_record_id===p.id&&x.page_number===p.page);if(!page){page=makeCoverage(p);S.content.pages.push(page);}page.notes=e.target.selectedOptions[0].text;changed();};if($('#check-current'))$('#check-current').onclick=()=>{let page=S.content.pages.find(x=>x.source_record_id===p.id&&x.page_number===p.page);if(!page){page=makeCoverage(p);S.content.pages.push(page);}if(p.role==='attachment'&&!page.notes.trim()){toast('Choose how the attachment was used, or add a note in Page details.');$('#attachment-use')?.focus();return;}page.reviewed=true;page.regions=['Whole page: all food rows, notes and clarifications for this date'];changed();renderPageCheck();if(S.tab==='pages')renderEditor();};if($('#page-details'))$('#page-details').onclick=()=>{S.tab='pages';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab==='pages'));renderEditor();document.querySelector(`[data-coverage-index="${S.content.pages.findIndex(x=>x.source_record_id===p.id&&x.page_number===p.page)}"]`)?.scrollIntoView({block:'nearest'});};}
function makeCoverage(p){return {source_record_id:p.id,page_number:p.page,classification:p.role==='main'?'food_record':'clarification',regions:[],notes:'',source_incomplete:false,reviewed:false};}
function mealName(id){const e=S.content.events.find(x=>x.event_id===id);return e?`Time: ${e.time.normalized||e.time.raw||'Not recorded'} · Label: ${e.meal_label.normalized||e.meal_label.raw||'Not recorded'}`:'Time: Not recorded · Label: Not recorded';}
function mealFoods(id){return S.content.items.filter(x=>x.event_id===id).map(x=>x.description.normalized||x.description.raw||'Unknown food').join(', ')||'No food items';}
function transformScan(){$('#zoom-label').textContent=S.zoom+'%';$('#image-layer').style.width=S.zoom+'%';$('#image-layer').style.transform=`rotate(${S.rotate}deg)`;}
function jump(evidence){if(!evidence)return toast('No direct source evidence. Inspect the inheritance reference.');const i=pages().findIndex(p=>p.id===evidence.source_record_id&&p.page===evidence.page_number);if(i<0)return toast('Evidence refers to an unavailable source page.');S.page=i;showPage(evidence);}
function itemTiming(i,write=false){
  const item=S.content.items[i];let event=S.content.events.find(e=>e.event_id===item.event_id);
  if(!event)throw new Error('Food timing is unavailable. Reload the review.');
  if(write&&S.content.items.filter(x=>x.event_id===event.event_id).length>1){
    event=clone(event);event.event_id=uid('meal');S.content.events.push(event);item.event_id=event.event_id;
  }
  return event;
}
function at(path,write=false){const bits=path.split('.');if(bits[0]==='itemTiming')return bits.slice(2).reduce((o,k)=>o[k],itemTiming(Number(bits[1]),write));return bits.reduce((o,k)=>o[k],S.content);}
function set(path,value){const bits=path.split('.');const key=bits.pop();const parent=bits.length?at(bits.join('.')):S.content;parent[key]=value;changed();}
function valueField(path,title){const v=at(path);if(v.metadata_reference)return `<div class="field"><label>${esc(title)}</label><input value="${esc(v.normalized)}" readonly aria-label="${esc(title)} from metadata"><small>From metadata · ${esc(v.metadata_reference.record_id)}</small></div>`;return `<div class="field"><div class="field-heading"><label>${esc(title)}</label><button type="button" data-source="${path}" class="quiet">View source</button></div>${input(v.normalized,`data-value="${path}" placeholder="${esc(({not_recorded:'Not recorded',illegible:'Illegible',ambiguous:'Uncertain',not_applicable:'Not applicable'})[v.missing_reason]||'Unknown')}" aria-label="${esc(title)} normalized" ${editable()?'':'readonly'}`)}<details class="field-details"><summary>Original text & evidence${v.inherited_from?' · inherited':''}</summary>${input(v.raw,`data-raw="${path}" placeholder="Original handwriting / raw text" aria-label="${esc(title)} raw" ${editable()?'':'readonly'}`)}${v.normalized===null?select([['not_recorded','Not recorded'],['illegible','Illegible'],['ambiguous','Uncertain'],['not_applicable','Not applicable']],v.missing_reason,`data-missing="${path}" aria-label="${esc(title)} missing reason" ${editable()?'':'disabled'}`):''}<small>${v.inherited_from?'Inherited from '+esc(v.inherited_from):`${v.evidence.length} source references`}</small><button type="button" data-evidence="${path}" class="quiet small" ${editable()?'':'disabled'}>Edit evidence</button></details></div>`;}

function textField(path,title,multiline=false){const attrs=`data-text="${path}" ${editable()?'':'readonly'}`;return field(title,multiline?`<textarea ${attrs}>${esc(at(path))}</textarea>`:input(at(path),attrs));}
function coverageProblems(){return pages().flatMap(p=>{const c=S.content?.pages.find(x=>x.source_record_id===p.id&&x.page_number===p.page);const reason=!c?'Coverage entry missing':!c.reviewed?'Confirmation required':c.classification!=='blank'&&!c.regions.some(x=>x.trim())?'Checked regions required':null;return reason?[{...p,reason}]:[];});}
function confirmedPages(){return pages().length-coverageProblems().length;}
function showCoverage(){S.tab='pages';document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab==='pages'));renderEditor();$('#editor').scrollTop=0;const first=coverageProblems()[0];if(first)jump({source_record_id:first.id,page_number:first.page,region:first.reason});}
function renderEditor(){if(!S.content){$('#editor').innerHTML='<div class="empty"><h2>No draft yet</h2><p>Assign a reviewer to start manual transcription, or generate an AI draft using the extraction command.</p></div>';return;}
  let html='';
  if(S.tab==='items'){
    html=`<div class="section-head"><div><h2>Food items</h2></div>${editable()?'<button data-action="add-item">+ Add item</button>':''}</div>${!editable()?`<p class="read-only">${S.detail.approved_id?'Approved for research. This version is read only.':S.detail.task?.status==='submitted'?(S.me?.offline?'Your review is saved. To make a correction, click Edit review above, then submit again and export a new result ZIP.':'Your review is submitted and saved. You can return to the queue.'):owner()?'Preview only. Choose Start my review to check or edit this day.':'Read-only preview. Use Review & help for clarification.'}</p>`:''}`;
    html+=S.content.items.map((x,i)=>`<details class="item" ><summary><span class="item-number">${String(i+1).padStart(2,'0')}</span><span><b>${esc(x.description.normalized||x.description.raw||'Unknown food')}</b><small>${esc(x.amount.normalized||'Amount unknown')} ${esc(x.unit.normalized||'')} · ${esc(mealName(x.event_id))}</small><small>${esc([x.brand.normalized,x.preparation.normalized,x.raw_or_cooked.normalized].filter(Boolean).join(" · "))}</small></span><button data-quick-source="${i}" class="quiet small">View source</button><span class="edit-hint">${editable()?'Edit':'Details'} ▾</span></summary><div class="item-body">${valueField(`items.${i}.description`,'Food / beverage')}<div class="two-col">${valueField(`itemTiming.${i}.time`,'Time')}${valueField(`itemTiming.${i}.meal_label`,'Label (optional)')}</div><div class="two-col">${valueField(`items.${i}.amount`,'amount')}${valueField(`items.${i}.unit`,'unit')}</div><details class="additional-fields"><summary>Additional details & notes</summary>${valueField(`itemTiming.${i}.place`,'Place')}${['brand','preparation','measurement_method','raw_or_cooked'].map(k=>valueField(`items.${i}.${k}`,k.replaceAll('_',' '))).join('')}<div class="two-col">${field('Numeric quantity',input(x.quantity,`type="number" min="0" step="any" data-number="items.${i}.quantity" ${editable()?'':'readonly'}`))}${field('Upper quantity (range)',input(x.quantity_max,`type="number" min="0" step="any" data-number="items.${i}.quantity_max" ${editable()?'':'readonly'}`))}</div>${textField(`items.${i}.notes`,'Reviewer notes',true)}</details><button data-item-source="${i}" class="quiet">↗ Item evidence</button>${editable()?`<button data-evidence="items.${i}" class="quiet">Edit item evidence</button>`:''}${editable()?`<div class="item-tools"><button data-split="${i}">Split item</button><button data-merge="${i}">Merge into this item</button><button data-delete="${i}" class="danger">Delete item</button></div>`:''}</div></details>`).join('');
    if(!S.content.items.length)html+='<p class="empty">No food items transcribed yet.</p>';
  }
  if(S.tab==='pages')html=`<h2>Confirm source pages</h2><p class="coverage-summary">${confirmedPages()} of ${pages().length} pages confirmed</p><p class="read-only">Use <b>I checked the whole page</b> below the scan for a full-page check. Use the controls here for partial checks or corrections.</p>${coverageProblems().length?`<ul class="coverage-pending">${coverageProblems().map(p=>`<li>${esc(p.id)} · Page ${p.page}: ${esc(p.reason)}</li>`).join('')}</ul>`:''}${editable()?'<button data-action="sync-pages">Add missing source pages</button>':''}<p class="muted">Confirm the regions you inspected, including attachments. Explain how each attachment was used or why it did not change the record.</p>${S.content.pages.map((p,i)=>`<div class="page-card" data-coverage-index="${i}"><div class="section-head"><h3>${esc(p.source_record_id)} · Page ${p.page_number}</h3><button data-page-jump="${i}">View source</button></div><label class="checkline source-confirmation"><input type="checkbox" data-bool="pages.${i}.reviewed" ${p.reviewed?'checked':''} ${editable()?'':'disabled'}> I have reviewed this source page</label>${field('Page type',select(['food_record','clarification','recipe','blank','other'],p.classification,`data-text="pages.${i}.classification" ${editable()?'':'disabled'}`))}${field('Regions checked (one per line)',`<textarea data-regions="${i}" ${editable()?'':'readonly'}>${esc(p.regions.join('\n'))}</textarea>`)}${textField(`pages.${i}.notes`,'Coverage / attachment clarification notes',true)}<details class="additional-fields"><summary>Report a source problem</summary><label class="checkline"><input type="checkbox" data-bool="pages.${i}.source_incomplete" ${p.source_incomplete?'checked':''} ${editable()?'':'disabled'}> Source appears incomplete</label></details></div>`).join('')}`;
  if(S.tab==='issues')html=`<h2>Review issues</h2><p class="muted">Check these reminders against the source. Notes are optional; no per-issue confirmation is required. Items marked “Correction required” need a data or source correction before approval.</p>${S.content.issues.map((x,i)=>`<div class="issue"><span class="badge ${S.detail.approval_blocking_codes?.includes(x.code)?'amber':''}">${S.detail.approval_blocking_codes?.includes(x.code)?'Correction required':'Reminder'}</span><h3>${esc(x.code.replaceAll('_',' '))}</h3><small>${esc(x.target===S.detail.record_id?'This day':x.target)}</small><p>${esc(x.message)}</p><details ${x.resolution?'open':''}><summary>Optional note</summary>${field('Note (optional)',`<textarea data-resolution="${i}" data-issue-code="${esc(x.code)}" data-issue-target="${esc(x.target)}" ${editable()?'':'readonly'} placeholder="Add context only when useful…">${esc(x.resolution)}</textarea>`)}</details></div>`).join('')||'<p>No issues recorded.</p>'}`;
  if(S.tab==='review')html=reviewPanel();
  $('#editor').innerHTML=html;bindEditor();
}
function changed(){document.querySelectorAll('details.item').forEach((el,i)=>{const item=S.content?.items[i];const title=el.querySelector('summary b');const detail=el.querySelector('summary small');if(item&&title){title.textContent=item.description.normalized||item.description.raw||'Unknown food';if(detail)detail.textContent=`${item.amount.normalized||'Amount unknown'} ${item.unit.normalized||''} · ${mealName(item.event_id)}`;}});if($('#confirm-sources'))$('#confirm-sources').textContent=`Pages checked: ${confirmedPages()}/${pages().length}`;if($('.coverage-summary'))$('.coverage-summary').textContent=`${confirmedPages()} of ${pages().length} pages confirmed`;if($('.coverage-pending'))$('.coverage-pending').innerHTML=coverageProblems().map(p=>`<li>${esc(p.id)} · Page ${p.page}: ${esc(p.reason)}</li>`).join('');S.dirty=true;S.epoch++;if($('#save-status'))$('#save-status').textContent=S.decision?'Unsaved adjudication':'Unsaved changes';clearTimeout(S.timer);if(!S.decision&&!S.conflict)S.timer=setTimeout(save,900);}
async function save(){clearTimeout(S.timer);if(S.saving){await S.saving;if(S.dirty&&!S.conflict)return save();return;}if(!S.dirty||S.decision||S.conflict||!S.detail?.task)return;
  const epoch=S.epoch, content=clone(S.content), task=S.detail.task;$('#save-status').textContent='Saving…';
  S.saving=(async()=>{try{const result=await api('/tasks/'+task.id,{revision:task.revision,content,reason:S.editReason||'Draft saved'},'PUT');task.revision=result.revision;task.status='in_progress';if(epoch===S.epoch){const issuesChanged=JSON.stringify(S.content.issues.map(x=>[x.code,x.target,x.message]))!==JSON.stringify(result.content.issues.map(x=>[x.code,x.target,x.message]));S.content=result.content;if(S.tab==='issues'&&issuesChanged)renderEditor();S.dirty=false;S.editReason=null;$('#save-status').textContent='All changes saved';}else $('#save-status').textContent='Saving newer changes…';}catch(e){$('#save-status').textContent='Not saved';if(e.status===409||e.status===403){S.conflict=true;$('#conflict-banner').hidden=false;$('#conflict-banner').innerHTML=`${esc(e.message)} <button id="download-draft">Download unsaved draft</button><button id="reload-draft">Reload record</button>`;$('#download-draft').onclick=()=>download(S.detail.record_id+'-unsaved.json',S.content);$('#reload-draft').onclick=async()=>{if(await ask('Discard unsaved changes and load the current record?')){S.dirty=false;openRecord(S.detail.record_id);}};}else if(e.status===401){toast('Your session expired. Sign in again; your unsaved draft remains in this tab.');auth();}else{toast(e.message+(e.fields?' '+e.fields.slice(0,3).map(f=>f.path+': '+f.message).join('; '):''));}}finally{S.saving=null;}})();await S.saving;
}
function bindEditor(){
  document.querySelectorAll('[data-quick-source]').forEach(b=>b.onclick=e=>{e.preventDefault();e.stopPropagation();jump(S.content.items[Number(b.dataset.quickSource)].evidence[0]);});
  document.querySelectorAll('[data-value]').forEach(el=>el.oninput=()=>{const v=at(el.dataset.value,true);v.normalized=el.value.trim()||null;v.missing_reason=v.normalized?null:(v.missing_reason||'not_recorded');if(v.normalized&&!v.evidence.length&&!v.inherited_from){const parts=el.dataset.value.split('.');if(parts[0]==='items')v.evidence=clone(S.content.items[Number(parts[1])].evidence);}changed();});
  document.querySelectorAll('[data-raw]').forEach(el=>el.oninput=()=>{at(el.dataset.raw,true).raw=el.value||null;changed();});document.querySelectorAll('[data-missing]').forEach(el=>el.onchange=()=>{at(el.dataset.missing,true).missing_reason=el.value;changed();});
  document.querySelectorAll('[data-text]').forEach(el=>el.oninput=()=>set(el.dataset.text,el.value));document.querySelectorAll('[data-number]').forEach(el=>el.onchange=()=>set(el.dataset.number,el.value===''?null:Number(el.value)));document.querySelectorAll('[data-bool]').forEach(el=>el.onchange=()=>{set(el.dataset.bool,el.checked);renderPageCheck();});document.querySelectorAll('[data-regions]').forEach(el=>el.onchange=()=>{S.content.pages[Number(el.dataset.regions)].regions=el.value.split('\n').map(x=>x.trim()).filter(Boolean);changed();});document.querySelectorAll('[data-resolution]').forEach(el=>el.oninput=()=>{const issue=S.content.issues.find(x=>x.code===el.dataset.issueCode&&x.target===el.dataset.issueTarget);if(issue){issue.resolution=el.value.trim()||null;changed();}});
  document.querySelectorAll('[data-source]').forEach(el=>el.onclick=()=>{const v=at(el.dataset.source);if(v.evidence.length)jump(v.evidence[0]);else toast('Inherited from: '+(v.inherited_from||'no reference'));});document.querySelectorAll('[data-evidence]').forEach(el=>el.onclick=()=>evidenceDialog(el.dataset.evidence));document.querySelectorAll('[data-item-source]').forEach(el=>el.onclick=()=>jump(S.content.items[Number(el.dataset.itemSource)].evidence[0]));document.querySelectorAll('[data-page-jump]').forEach(el=>el.onclick=()=>{const p=S.content.pages[Number(el.dataset.pageJump)];jump({...p,region:'Page coverage'});});
  document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>editAction(el.dataset.action));document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=async()=>{const why=await ask('Why should this food item be removed?', true);if(!why?.trim())return;S.content.items.splice(Number(el.dataset.delete),1);S.editReason='Deleted food item: '+why;changed();renderEditor();});document.querySelectorAll('[data-split]').forEach(el=>el.onclick=()=>splitItem(Number(el.dataset.split)));document.querySelectorAll('[data-merge]').forEach(el=>el.onclick=()=>mergeItem(Number(el.dataset.merge)));
  document.querySelectorAll('[data-delete-day]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.deleteDay);if(S.content.events.some(x=>x.day_id===S.content.days[i].day_id))return toast('Move or remove its meals first.');S.content.days.splice(i,1);changed();renderEditor();});document.querySelectorAll('[data-delete-event]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.deleteEvent);if(S.content.items.some(x=>x.event_id===S.content.events[i].event_id))return toast('Move or remove its food items first.');S.content.events.splice(i,1);changed();renderEditor();});
  if(S.tab==='review')bindReview();
}
function evidenceDialog(path){const v=at(path);const refs=clone(v.evidence);modal('Field evidence',`<p>Link the field to the source region that supports it. Inheritance must refer to an existing day, event or item ID.</p><div id="refs"></div><button id="add-ref">+ Add source reference</button>${field('Inheritance reference (optional)',input(v.inherited_from,'id="inherit"'))}<button id="apply-evidence" class="primary">Apply evidence</button>`,()=>{
  function draw(){$('#refs').innerHTML=refs.map((r,i)=>`<fieldset><legend>Reference ${i+1}</legend>${field('Source page',select(pages().map((p,j)=>[String(j),`${p.id} / ${p.page}`]),String(pages().findIndex(p=>p.id===r.source_record_id&&p.page===r.page_number)),`data-ref-page="${i}"`))}${field('Region / row locator',input(r.region,`data-ref-region="${i}"`))}${field('Verbatim transcription',input(r.transcription_raw,`data-ref-text="${i}"`))}${field('Bounding box (optional: x1, y1, x2, y2; 0–1)',input(r.bbox?.join(', '),`data-ref-box="${i}"`))}<button data-ref-remove="${i}">Remove reference</button></fieldset>`).join('');document.querySelectorAll('[data-ref-page]').forEach(e=>e.onchange=()=>{const p=pages()[Number(e.value)];Object.assign(refs[Number(e.dataset.refPage)],{source_record_id:p.id,page_number:p.page});});document.querySelectorAll('[data-ref-region]').forEach(e=>e.oninput=()=>refs[Number(e.dataset.refRegion)].region=e.value);document.querySelectorAll('[data-ref-text]').forEach(e=>e.oninput=()=>refs[Number(e.dataset.refText)].transcription_raw=e.value);document.querySelectorAll('[data-ref-box]').forEach(e=>e.onchange=()=>refs[Number(e.dataset.refBox)].bbox=e.value.trim()?e.value.split(',').map(Number):null);document.querySelectorAll('[data-ref-remove]').forEach(e=>e.onclick=()=>{refs.splice(Number(e.dataset.refRemove),1);draw();});}
  draw();$('#add-ref').onclick=()=>{const p=pages()[S.page];refs.push({source_record_id:p.id,page_number:p.page,region:'',transcription_raw:'',bbox:null});draw();};$('#apply-evidence').onclick=()=>{if(refs.some(r=>!r.region.trim()))return toast('Each reference needs a source region.');const target=at(path,true);target.evidence=refs;if('inherited_from' in target)target.inherited_from=$('#inherit').value.trim()||null;changed();$('#modal').close();renderEditor();};});}
async function editAction(action){if(action==='sync-pages'){for(const p of pages()){if(!S.content.pages.some(x=>x.source_record_id===p.id&&x.page_number===p.page))S.content.pages.push({source_record_id:p.id,page_number:p.page,classification:p.role==='main'?'food_record':'clarification',regions:[],notes:'',source_incomplete:false,reviewed:false});}}if(action==='add-day')S.content.days.push({day_id:uid('day'),date:unknown()});if(action==='add-event'){if(!S.content.days.length)return toast('Add a day first.');S.content.events.push({event_id:uid('meal'),day_id:S.content.days[0].day_id,time:unknown(),meal_label:unknown(),place:unknown()});}if(action==='add-item'){if(!S.content.days.length)return toast('The intake date is missing. Contact the study owner.');const region=await ask('Which source row or region contains this food?', true);if(!region?.trim())return;const p=pages()[S.page];const event={event_id:uid('meal'),day_id:S.content.days[0].day_id,time:unknown(),meal_label:unknown(),place:unknown()};S.content.events.push(event);const x={item_id:uid('item'),event_id:event.event_id,quantity:null,quantity_max:null,evidence:[{source_record_id:p.id,page_number:p.page,region,transcription_raw:'',bbox:null}],notes:''};for(const k of ['description','amount','unit','brand','preparation','measurement_method','raw_or_cooked'])x[k]=unknown();S.content.items.push(x);}changed();renderEditor();}
async function splitItem(i){const x=S.content.items[i];const why=await ask('Describe why this entry contains multiple foods.', true);if(!why?.trim())return;const y=clone(x);y.item_id=uid('item');for(const item of [x,y]){item.quantity=null;item.quantity_max=null;item.amount=unknown();item.notes+='\nSplit from '+x.item_id+': '+why;}S.content.items.splice(i+1,0,y);S.content.issues.push({code:'human_split_check',severity:'blocking',target:y.item_id,message:'Confirm separate descriptions and amounts after splitting an entry.',resolution:null});S.editReason='Split food item: '+why;changed();renderEditor();}
function mergeItem(i){const x=S.content.items[i];const options=S.content.items.map((y,j)=>[String(j),`${y.item_id}: ${y.description.normalized||'Unknown food'}`]).filter(([j])=>Number(j)!==i);if(!options.length)return toast('At least two food items are needed.');modal('Merge food entries',`<p>Amounts will be cleared for you to verify. Both source references are retained.</p>${field('Entry to merge',select(options,options[0][0],'id="merge-index"'))}${field('Reason',input('','id="merge-reason"'))}<button id="merge-confirm" class="primary">Merge entries</button>`,()=>{$('#merge-confirm').onclick=()=>{const why=$('#merge-reason').value.trim();if(!why)return toast('Explain the merge.');const j=Number($('#merge-index').value),y=S.content.items[j];x.evidence.push(...clone(y.evidence));x.quantity=null;x.quantity_max=null;x.amount=unknown();x.notes+=`\nMerged ${y.item_id}: ${why}\n${y.notes}`;S.content.items.splice(j,1);S.content.issues.push({code:'human_merge_check',severity:'blocking',target:x.item_id,message:'Confirm description and amount after merging entries.',resolution:null});S.editReason='Merged food items: '+why;changed();$('#modal').close();renderEditor();};});}
function reviewPanel(){const d=S.detail;return `<h2>Review & decisions</h2><p class="muted">${d.blind_review?'Independent review: other reviewers’ answers remain hidden until you submit.':'Submissions are immutable. A decision records the final content and its rationale.'}</p><button id="history">View save history</button>${d.task&&d.task.status!=='submitted'?'<button id="ask-help">Ask for clarification</button>':''}<h3>Assignments</h3>${d.tasks.map(t=>`<div class="message"><b>${esc(memberName(t.assignee_id))}</b> · ${esc(t.status)}${owner()&&!['returned','stale','cancelled'].includes(t.status)?`<button data-return="${esc(t.id)}" class="quiet">Return / reassign</button>`:''}</div>`).join('')||'<p>No assignments yet.</p>'}${owner()?`<h3>Independent submissions (${d.submissions.length} / ${d.required_reviews})</h3>${d.submissions.map((sub,i)=>`<div class="comparison"><b>${esc(memberName(sub.reviewer_id))}</b><small>${esc(sub.created_at)}</small><p>${sub.content.items.length} food items · ${sub.content.issues.length} review reminders / checks</p><button data-compare="${i}">Inspect submission</button><button data-decide="${i}">Use as decision draft</button></div>`).join('')}${d.decision?`<p class="read-only">Decision recorded: ${esc(d.decision.reason)}</p>`:''}${S.decision?'<button id="decision-save" class="primary">Record adjudication</button>':''}<button id="exclude" class="danger">Exclude record</button><button id="restore-record">Restore excluded record</button>`:''}<h3>Clarification requests</h3>${d.help.map(h=>`<div class="message"><strong>${esc(h.question)}</strong><small>${esc(h.status)} · Helper: ${esc(h.helper_id?memberName(h.helper_id):'not assigned')}</small>${h.messages.map(m=>`<p><b>${esc(memberName(m.actor_id))}</b>: ${esc(m.message||m.text)}</p>`).join('')}${owner()&&h.status!=='closed'?`<button data-help-assign="${esc(h.id)}">Assign helper</button>`:''}${h.status!=='closed'?`<button data-help-reply="${esc(h.id)}">Reply / close</button>`:''}</div>`).join('')||'<p class="muted">No clarification requests.</p>'}`;}
function bindReview(){const d=S.detail;$('#history').onclick=async()=>{try{const h=await api('/records/'+d.record_id+'/history');modal('Save history',h.edits.map((x,i)=>`<div class="history"><b>Revision ${x.revision}</b> · ${esc(x.at)}<p>${esc(x.reason)}</p>${editable()?`<button data-restore="${i}">Restore as a new edit</button>`:''}</div>`).join('')+'<h3>Audit events</h3>'+h.events.map(x=>`<p>${esc(x.at)} · ${esc(x.action)}</p>`).join(''),()=>document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{S.content=clone(h.edits[Number(b.dataset.restore)].content);S.editReason='Restored prior saved revision';changed();$('#modal').close();renderEditor();}));}catch(e){toast(e.message);}};
  if($('#ask-help'))$('#ask-help').onclick=async()=>{const question=await ask('What needs clarification? Include the source page or food item.', true);if(!question?.trim())return;await save();if(S.dirty)return;try{await api('/tasks/'+d.task.id+'/help',{question});await openRecord(d.record_id);S.tab='review';renderEditor();}catch(e){toast(e.message);}};
  document.querySelectorAll('[data-return]').forEach(b=>b.onclick=async()=>{const reason=await ask('Why is this assignment being returned? A new assignment will start from the frozen candidate.', true);if(!reason?.trim())return;try{await api('/tasks/'+b.dataset.return+'/return',{reason});await openRecord(d.record_id);assignDialog([d.record_id]);}catch(e){toast(e.message);}});
  document.querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{compareSubmissions(Number(b.dataset.compare));});
  document.querySelectorAll('[data-decide]').forEach(b=>b.onclick=()=>{S.content=clone(d.submissions[Number(b.dataset.decide)].content);S.decision=true;S.dirty=true;S.tab='items';renderRecord();toast('Decision draft opened. Resolve differences, then record adjudication with a reason.');});
  if($('#decision-save'))$('#decision-save').onclick=saveDecision;
  if($('#exclude'))$('#exclude').onclick=async()=>{const reason=await ask('Why is this record excluded from research exports?', true);if(!reason?.trim())return;try{await api('/records/'+d.record_id+'/exclude',{reason});await queue();}catch(e){toast(e.message);}};
  if($('#restore-record'))$('#restore-record').onclick=async()=>{const reason=await ask('Why should this excluded record be restored?', true);if(!reason?.trim())return;try{await api('/records/'+d.record_id+'/restore',{reason});await openRecord(d.record_id);}catch(e){toast(e.message);}};
  document.querySelectorAll('[data-help-assign]').forEach(b=>b.onclick=()=>modal('Assign clarification helper',`<p>A helper cannot count as an independent reviewer for this record.</p>${field('Helper',select(memberOptions(),'','id="helper"'))}<button id="assign-helper" class="primary">Assign helper</button>`,()=>{$('#assign-helper').onclick=async()=>{try{await api('/help/'+b.dataset.helpAssign+'/assign',{helper_id:$('#helper').value});$('#modal').close();await openRecord(d.record_id);S.tab='review';renderEditor();}catch(e){toast(e.message);}};}));
  document.querySelectorAll('[data-help-reply]').forEach(b=>b.onclick=()=>modal('Clarification reply',`${field('Message','<textarea id="reply"></textarea>')}<label class="checkline"><input type="checkbox" id="close-help"> Mark request resolved</label><button id="send-reply" class="primary">Save reply</button>`,()=>{$('#send-reply').onclick=async()=>{try{await api('/help/'+b.dataset.helpReply+'/reply',{message:$('#reply').value,close:$('#close-help').checked});$('#modal').close();await openRecord(d.record_id);S.tab='review';renderEditor();}catch(e){toast(e.message);}};}));
}
function compareSubmissions(selected) {
  const subs=S.detail.submissions;
  function flatten(c){const result={'Record / subject':c.subject,'Record / notes':c.notes};for(const [group,id] of [['days','day_id'],['events','event_id'],['items','item_id'],['pages','source_record_id'],['issues','code']])for(const item of c[group])for(const [key,value] of Object.entries(item)){if(key===id)continue;const entity=group==='pages'?item[id]+'/'+item.page_number:group==='issues'?item[id]+'/'+item.target:item[id];result[group+' / '+entity+' / '+key]=value;}return result;}
  const maps=subs.map(x=>flatten(x.content));const keys=[...new Set(maps.flatMap(m=>Object.keys(m)))];
  function display(v){if(v===undefined)return '<i>Entry absent</i>';if(v&&typeof v==='object'&&'normalized' in v)return `<b>${esc(v.normalized??'Unknown: '+v.missing_reason)}</b><small>Raw: ${esc(v.raw)}</small><small>${esc(v.evidence.map(e=>e.source_record_id+' / '+e.page_number+' / '+e.region).join('; ')||v.inherited_from||'No direct evidence')}</small>`;return esc(typeof v==='object'?JSON.stringify(v):v);}
  modal('Independent submission comparison',`<p>Entries align by stable IDs, not row position. Added, removed, split and merged entries remain separate for the adjudicator to reconcile against the scan.</p><div class="table-scroll"><table><thead><tr><th>Field / stable ID</th>${subs.map(x=>`<th>${esc(memberName(x.reviewer_id))}</th>`).join('')}</tr></thead><tbody>${keys.map(k=>`<tr class="${new Set(maps.map(m=>JSON.stringify(m[k]))).size>1?'difference':''}"><td>${esc(k)}</td>${maps.map(m=>`<td>${display(m[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><button id="decision-from-comparison" class="primary">Use ${esc(memberName(subs[selected].reviewer_id))} as decision draft</button>`,()=>{$('#decision-from-comparison').onclick=()=>{S.content=clone(subs[selected].content);S.decision=true;S.dirty=true;S.tab='items';$('#modal').close();renderRecord();};});
}
async function submit(){if(coverageProblems().length){showCoverage();toast('Confirm the listed source pages before submitting. Use “I checked the whole page” below each scan, or record a partial check in Page details.');return;}await save();if(S.dirty)return toast('Save all changes before submitting.');if(!await ask(S.me?.offline?'Submit this review? You can use Edit review if you later find a correction.':'Submit this review? Confirm that you have checked the source pages and issue reminders. Your submission will be frozen.'))return;try{await api('/tasks/'+S.detail.task.id+'/submit',{revision:S.detail.task.revision});toast('Review submitted. Your work is saved.');await openRecord(S.detail.record_id);}catch(e){if(e.message.includes('source page'))showCoverage();toast(e.message);}}
async function saveDecision(){const reason=await ask('Explain how you resolved disagreements and selected the final values.', true);if(!reason?.trim())return;try{await api('/records/'+S.detail.record_id+'/adjudicate',{content:S.content,reason});S.dirty=false;S.decision=false;toast('Adjudication recorded. The record can now be checked for approval.');await openRecord(S.detail.record_id);}catch(e){toast(e.message);}}
async function team(){S.detail=null;S.members=await api('/members');const p=await api('/policy');$('#breadcrumb').textContent='People & policy';$('#screen').innerHTML=`<div class="page"><h1>People & policy</h1><p class="muted">Manage project members and review requirements.</p><div class="two-col"><section class="panel padded"><h2>Invite a colleague</h2><form id="invite-form">${field('Name',input('','name="name" required'))}${field('Email',input('','name="email" type="email" required'))}${field('Role',select(['reviewer','owner'],'reviewer','name="role"'))}<button class="primary">Create invitation link</button></form><div id="invite-result"></div></section><section class="panel padded"><h2>Review policy</h2><p class="muted">Saving a new policy invalidates current reviews and approvals. Existing releases remain unchanged.</p><form id="policy-form">${field('Reviews per record',select([['1','One'],['2','Two']],String(p.settings.review_count),'name="review_count"'))}${field('Reviews for high-risk records',select([['1','One'],['2','Two']],String(p.settings.high_risk_review_count),'name="high_risk_review_count"'))}${field('Random double-review sample (%)',input(p.settings.sample_percent,'name="sample_percent" type="number" min="0" max="100" required'))}${field('Reproducible sampling seed',input(p.settings.sample_seed,'name="sample_seed" required'))}<label class="checkline"><input name="high_risk_flags" type="checkbox" ${p.settings.high_risk_flags?'checked':''}> Treat source flags and blockers as high risk</label><button>Save new policy version</button></form></section></div><section class="panel padded"><h2>Project members</h2>${S.members.map(m=>`<div class="member"><div><b>${esc(m.name)}</b><small>${esc(m.email)} · ${esc(m.role)} · ${m.active?'active':'revoked'}</small></div>${m.id!==S.me.id?`<button data-member="${esc(m.id)}" data-active="${m.active?'0':'1'}">${m.active?'Revoke access':'Reactivate'}</button><button data-reinvite="${esc(m.id)}">Reset invitation</button>`:''}</div>`).join('')}</section></div>`;
  $('#invite-form').onsubmit=async e=>{e.preventDefault();try{const r=await api('/members',Object.fromEntries(new FormData(e.target)));inviteLink(r);}catch(e){toast(e.message);}};$('#policy-form').onsubmit=async e=>{e.preventDefault();if(!await ask('Create a new policy and require fresh reviews for current records?'))return;const f=new FormData(e.target);try{await api('/policy',{review_count:Number(f.get('review_count')),high_risk_review_count:Number(f.get('high_risk_review_count')),sample_percent:Number(f.get('sample_percent')),sample_seed:f.get('sample_seed'),high_risk_flags:f.has('high_risk_flags')});toast('Policy updated.');await team();}catch(e){toast(e.message);}};
  document.querySelectorAll('[data-member]').forEach(b=>b.onclick=async()=>{try{await api('/members/'+b.dataset.member+'/status',{active:b.dataset.active==='1'});await team();}catch(e){toast(e.message);}});document.querySelectorAll('[data-reinvite]').forEach(b=>b.onclick=async()=>{if(!await ask('Reset this member’s password and revoke existing sessions?'))return;try{inviteLink(await api('/members/'+b.dataset.reinvite+'/invite',{}));}catch(e){toast(e.message);}});
}
function inviteLink(r){const link=location.origin+'/#invite='+r.token;modal('Invitation ready',`<p>Share this link privately with the intended colleague. It expires in 24 hours. No email has been sent.</p><div class="link-box">${esc(link)}</div><button id="copy-link">Copy link</button>`,()=>{$('#copy-link').onclick=async()=>{await navigator.clipboard.writeText(link);toast('Invitation copied.');};});}
async function releases(){S.detail=null;const rows=await api('/releases');$('#breadcrumb').textContent='Research releases';$('#screen').innerHTML=`<div class="page"><h1>Research releases</h1><p class="muted">Each release contains approved data, source provenance, review history and a processing report for the full project.</p><section class="panel padded">${rows.map(r=>`<div class="member"><div><b>${esc(r.created_at)}</b><small>${r.records} records · ${esc(r.id)}</small><small>SHA-256 ${esc(r.checksum)}</small></div><a class="button" href="/api/releases/${esc(r.id)}/download">Download archive</a></div>`).join('')||'<p>No research releases yet. Select approved records in the review queue to create one.</p>'}</section></div>`;}
function importPage(){S.detail=null;$('#breadcrumb').textContent='Import records';$('#screen').innerHTML=`<div class="page"><h1>Add records & attachments</h1><p class="muted">Import one record or a batch. Attachments such as R0004-A1.pdf are grouped with R0004. Preview the grouping before importing.</p><section class="panel padded"><form id="import-form">${field('Scanned PDFs (one or many; up to 10 MB each)','<input name="files" type="file" accept=".pdf" multiple required>')}${field('Metadata file (JSON, CSV or XLSX)','<input name="metadata_file" type="file" accept=".json,.csv,.xlsx">')}${field('Or metadata JSON','<textarea name="metadata_json" rows="6" placeholder=\'[ {"record_id": "R0004", "subject_id": "P001"} ]\'>[]</textarea>')}<p class="muted">Maximum request size: 64 MB. Importing does not contact an AI provider. New attachments invalidate previous review tasks for their record.</p><button class="primary">Preview grouping</button></form><div id="import-preview"></div></section></div>`;$('#import-form').onsubmit=async e=>{e.preventDefault();try{const r=await api('/import/preview',new FormData(e.target));$('#import-preview').innerHTML=`<h2>Import preview</h2><pre>${esc(JSON.stringify(r.report,null,2))}</pre><button id="confirm-import" class="primary">Confirm import</button>`;$('#confirm-import').onclick=async()=>{try{const result=await api('/import/confirm',{token:r.token});toast('Import complete. New or changed records are ready for extraction or manual assignment.');modal('Import receipt',`<pre>${esc(JSON.stringify(result,null,2))}</pre>`);}catch(e){toast(e.message);}};}catch(e){toast(e.message);}};}
