  $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand">Offline Reviewer</div><nav><button id="offline-queue">Package overview</button></nav><div class="sidebar-bottom"><strong>${esc(S.me.name)}</strong><small>Saved on this computer</small></div></aside><main><header class="topline"><span id="breadcrumb">Package overview</span><span class="muted">Offline review</span></header><div id="screen"></div></main></div>`;
  $('#offline-queue').onclick=()=>navigate('queue');
